// ⚠️ Nodo de ejemplo. Reemplázalo por la lectura del Excel:
//   Read Binary File → Spreadsheet File (xlsx) → (este mapeo).
// Cada item de salida = UNA fila del grupo. El nodo Postgres siguiente
// se ejecuta una vez por item (fila).
//
// Ajusta el nombre de las columnas según tu Excel.
const rows = [
  { name: 'Grupo Ejemplo',   description: 'Importado desde Excel', is_active: true, is_doctor: false, external_id: 'EXT-001' },
  { name: 'Dr. Juan Pérez',  description: 'Grupo que es doctor',   is_active: true, is_doctor: true,  external_id: 'DOC-100' }
];

return rows.map((r) => ({ json: r }));

// Junta el resultado de todas las filas (rama doctor y rama solo-grupo)
// en un solo objeto.
const items = $input.all();
const created = items.map((it) => {
  const j = it.json || {};
  if (j.result) return j.result;                    // rama doctor (objeto json_build_object)
  return { group: j, doctor: null, role: null };    // rama solo-grupo (fila plana)
});

return [{
  json: {
    count: created.length,
    groups: created
  }
}];
